def generate_matrix(n):
    if n == 0:
        return []

    result = [[0] * n for _ in range(n)]
    num = 1

    while num <= n ** 2:
        # Fill top row
        for i in range(num - 1, num + n - 1):
            result[0][i] = num
            num += 1

        # Fill right column
        for j in range(1, num):
            result[j][n - 1] = num
            num += 1

        # Fill bottom row
        for k in range(n - 2, -1, -1):
            result[n - 1][k] = num
            num += 1

        # Fill left column
        for l in range(n - 2, 0, -1):
            result[l][0] = num
            num += 1

    return result

