def min_Swaps(s1, s2):
    # Initialize variables for tracking positions and count of swaps
    pos = [0] * len(s1)
    swap_count = 0

    # Iterate through both strings simultaneously
    for i in range(len(s1)):
        if s1[i] != s2[i]:
            # If characters differ, increment swap counter
            swap_count += 1

            # Update position array with current index
            pos[s1[i]] = i + 1

    # Calculate total swaps needed by summing up differences between indices
    return swap_count - max(pos) * (len(s1) - swap_count)

import heapq

def nth_super_ugly_number(n, primes):
    # Initialize the heap with the first n elements in the sequence
    heap = [(p * i, p * i) for p in primes for i in range(1, n)]

    # Extract the smallest element from the heap and add its next multiples to the heap
    while len(heap) > n:
        _, num = heapq.heappop(heap)
        for p in primes:
            heapq.heappush(heap, (num * p, num * p))

    return [x[0] for x in heap][n-1]

