def coin_change(S, m, n):
    # Initialize DP table with size (m+1) x (n+1)
    dp = [[0 for _ in range(n + 1)] for _ in range(m + 1)]

    # Fill the DP table
    for i in range(m + 1):
        for j in range(1, n + 1):
            if i == 0:
                dp[i][j] = float('inf')  # No coins available
            elif j == 0:
                dp[i][j] = 0  # Zero value when no items left
            elif S[i - 1] <= j:
                dp[i][j] = min(dp[i-1][j], 1 + dp[i][j-S[i-1]])
            else:
                dp[i][j] = dp[i-1][j]

    return dp[m][n]

