def find_closet(A, B, C, p, q, r):
    i = j = k = 0

    while i < len(A) and j < len(B) and k < len(C):
        if A[i] + B[j] + C[k] == p:
            return (A[i], B[j], C[k])

        elif A[i] + B[j] + C[k] < p:
            i += 1

        elif A[i] + B[j] + C[k] > p:
            j += 1

        k += 1

    # If no triplet found with sum equal to p, check for sums less than p
    while i < len(A) and j < len(B):
        if A[i] + B[j] + C[r-1] <= p:
            return (A[i], B[j], C[r-1])
        i += 1
        j += 1

    while j < len(B) and k < len(C):
        if A[p-q-j] + B[j] + C[k] <= p:
            return (A[p-q-j], B[j], C[k])
        j += 1
        k += 1

    return None

def heapify(arr, n, i):
    largest = i
    left = 2 * i + 1
    right = 2 * i + 2

    if left < n and arr[i] < arr[left]:
        largest = left

    if right < n and arr[largest] < arr[right]:
        largest = right

    if largest != i:
        arr[i], arr[largest] = arr[largest], arr[i]
        heapify(arr, n, largest)

def heap_sort(arr):
