    for i in range(n-1, 0, -1):
        arr[i], arr[0] = arr[0], arr[i]
        heapify(arr, i, 0)

def nCr_mod_p(n, r, p):
    if r > n:
        return 0
    elif r == 0 or r == n:
        return 1

    # Calculate nCr using Lucas' Theorem
    while r != 0 and n != 0:
        if r % 2 == 1:
            n = (n * (n - 1)) // 2 % p
        r //= 2
        n = (n * n) % p

    return n

