def roman_to_int(s):
    # Define Roman numerals and their corresponding values
    rom_val = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}

    # Initialize result variable
    res = 0

    # Iterate through the string in reverse order
    for i in range(len(s) - 1):
        # If current value is less than next one, subtract it from result
        if rom_val[s[i]] < rom_val[s[i + 1]]:
            res -= rom_val[s[i]]
        else:
            # Otherwise add it to result
            res += rom_val[s[i]]

    # Add last character's value to result
    res += rom_val[s[-1]]

    return res

