def min_sum_path(A):
    # Start from the second last row and move upwards
    for i in range(len(A) - 2, -1, -1):
        for j in range(i + 1):
            # Update the current cell with the minimum of its two children plus itself
            A[i][j] += min(A[i+1][j], A[i+1][j+1])

    # The top-left cell now contains the minimum sum path
    return A[0][0]

def find_Min_Sum(num):
    if num == 1:
        return 0

    min_sum = float('inf')

    for i in range(2, int(num**0.5) + 1):
        count = 0
        while num % i == 0:
            num //= i
            count += 1

        if count > 0:
            min_sum = min(min_sum, i * (count + 1))

    if num > 1:
        min_sum = min(min_sum, num)

    return min_sum

def counting_sort_for_radix(arr, exp):
    n = len(arr)
    output = [0] * n
    count = [0] * 10

    for i in range(n):
        index = arr[i] // exp
        count[index % 10] += 1

    for i in range(1, 10):
        count[i] += count[i - 1]

    i = n - 1
    while i >= 0:
        index = arr[i] // exp
        output[count[index % 10] - 1] = arr[i]
        count[index % 10] -= 1
        i -= 1

    for i in range(n):
        arr[i] = output[i]

def radix_sort(nums):
