def lbs(arr):
    n = len(arr)

    # Initialize two arrays to store the maximum length of increasing and decreasing subsequences ending at each index
    inc = [1] * n
    dec = [1] * n

    # Fill the 'inc' array (length of increasing subsequences)
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                inc[i] = max(inc[i], inc[j] + 1)

    # Fill the 'dec' array (length of decreasing subsequences)
    for i in range(n-2, -1, -1):
        for j in range(n-1, i, -1):
            if arr[i] > arr[j]:
                dec[i] = max(dec[i], dec[j] + 1)

    # The answer will be the maximum value from both 'inc' and 'dec' arrays
    return max(max(inc), max(dec))

def max_sum_increasing_subsequence(arr, n):
    # Initialize the DP table with zeros
    dp = [0] * n

    # Iterate through each element in the array
    for i in range(n):
        # Find the maximum value from the previous elements that is less than arr[i]
        prev_max = float('-inf')
        for j in range(i):
            if arr[j] < arr[i]:
                prev_max = max(prev_max, dp[j])

        # Update the DP table with the maximum sum found so far
        dp[i] = prev_max + arr[i]

    # Return the maximum value in the DP table
    return max(dp)

