def last_Two_Digits(N):
    fact = 1
    for i in range(2, N + 1):
        fact *= i

    # Remove trailing zeros by dividing out factors of 10
    while fact % 10 == 0:
        fact //= 10

    # Remove remaining factors of 10
    while fact >= 10:
        fact //= 10

    return fact % 100

