def count_Fac(n):
    if n <= 1:
        return 0

    factors = []
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)

    if n > 1:
        factors.append(n)

    unique_factors = set(factors)
    count = len(unique_factors)

    return count

def find_first_occurrence(A, x):
    left, right = 0, len(A) - 1

    while left <= right:
        mid = (left + right) // 2

        if A[mid] == x:
            # Check if this is the first occurrence by comparing with the previous element
            if mid == 0 or A[mid-1] != x:
                return mid
            else:
                right = mid - 1
        elif A[mid] < x:
            left = mid + 1
        else:
            right = mid - 1

    return -1

def jacobsthal_num(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1

    dp = [0] * (n + 1)
    dp[0] = 0
    dp[1] = 1

    for i in range(2, n + 1):
        dp[i] = dp[i - 1] + 2 * dp[i - 2]

    return dp[n]

