def second_frequent(input):
    frequency_dict = {}

    # Count the frequency of each string in the input list
    for item in input:
        if item in frequency_dict:
            frequency_dict[item] += 1
        else:
            frequency_dict[item] = 1

    # Find the maximum frequency
    max_frequency = max(frequency_dict.values())

    # Filter items with the maximum frequency
    max_items = [item for item, freq in frequency_dict.items() if freq == max_frequency]

    # Return the second most frequent item
