def sum_of_odd_factors(n):
    total_sum = 0
    # Iterate through all numbers from 1 to sqrt(n) to check for factors
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            # If both i and n/i are odd, add i to the sum
            if i % 2 != 0 and n // i % 2 != 0:
                total_sum += i
            # If only one of them is odd, add its corresponding even multiple to the sum
            elif i % 2 != 0 or n // i % 2 != 0:
                total_sum += n // i * 2
    return total_sum

