def find_Min_Swaps(arr, n):
    min_swaps = 0

    # Iterate through each element in the array
    for i in range(n - 1):
        # If the current element is greater than or equal to the next element,
        # increment the swap count by one
        if arr[i] >= arr[i + 1]:
            min_swaps += 1

