def smallest_multiple(n):
    if n <= 1:
        return 1

    # Initialize the DP array with the first number as its own multiple
    dp = [i for i in range(1, n+1)]

    # Iterate through the numbers starting from the second one
    for i in range(2, n+1):
        min_multiple = float('inf')

        # Check all previous numbers to see if they can be multiplied by the current number to get a smaller multiple
        for j in range(i-1, 0, -1):
            if dp[j] < min_multiple and (dp[j] * i) % j == 0:
                min_multiple = dp[j]

        # Update the minimum multiple found so far
        dp[i-1] = min_multiple

    # The result will be the last element in the DP array, which represents the smallest multiple of all numbers up to n
    return dp[-1]

def max_product(arr):
