def super_seq(X, Y, m, n):
    # Create two arrays for storing lengths of longest common suffixes 
    lcsuff = [[0 for k in range(n+1)] for l in range(m+1)]

    # Following steps build LCSuff[m+1][n+1] in bottom up fashion 
    for i in range(m + 1): 
        for j in range(n + 1): 
            if (i == 0 or j == 0): 
                lcsuff[i][j] = 0
            elif X[i-1] == Y[j-1]: 
                lcsuff[i][j] = lcsuff[i-1][j-1]+1
            else: 
                lcsuff[i][j] = max(lcsuff[i-1][j], lcsuff[i][j-1]) 

    # Following code is used to print LCS 
    index = lcsuff[m][n]
    lcs = [""] * (index+1)
    lcs[index] = ""
    i = m
    j = n
    while i > 0 and j > 0:
        if X[i - 1] == Y[j - 1]:
            lcs[index - 1] = X[i - 1]
            i -= 1
            j -= 1
            index -= 1
        elif lcsuff[i - 1][j] > lcsuff[i][j - 1]: 
            i -= 1
        else: 
            j -= 1

    return "".join(lcs)

