def min_subset_with_distinct_elements(ar, n):
    ar.sort()
    dp = [float('inf')] * n
    dp[0] = 0

    for i in range(1, n):
        dp[i] = dp[i-1]

        if ar[i] != ar[i-1]:
            if i > 1:
                dp[i] = min(dp[i], dp[i-2] + ar[i] + ar[i-1])
            else:
                dp[i] = min(dp[i], ar[i] + ar[i-1])

    return dp[n-1]

