def roman_to_int(s):
    roman_values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev_value = 0

    for char in reversed(s):
        value = roman_values[char]

        if value < prev_value:
            total -= value
        else:
            total += value

        prev_value = value

    return total

def min_sum_path(triangle):
    # Start from the second last row and move upwards
    for i in range(len(triangle) - 2, -1, -1):
        for j in range(len(triangle[i])):
            # Update the current cell with the minimum path sum
            triangle[i][j] += min(triangle[i+1][j], triangle[i+1][j+1])

    # The top-left element will contain the minimum path sum
    return triangle[0][0]

def modular_sum(arr, n, m):
    dp = [False] * (n + 1)
    dp[0] = True

    for num in arr:
        for i in range(n, num - 1, -1):
            if dp[i - num]:
                dp[i] = True
                break

    return any(dp[i] for i in range(1, n + 1) if i % m == 0)

