def lbs(arr):
    n = len(arr)
    if n == 1:
        return arr[0]

    # Initialize two arrays to store the length of the longest increasing subsequence ending at each index
    lis = [1] * n
    lds = [1] * n

    # Fill the LIS array from left to right
    for i in range(n):
        for j in range(i):
            if arr[j] < arr[i]:
                lis[i] = max(lis[i], lis[j] + 1)

    # Fill the LDS array from right to left
    for i in range(n-1, -1, -1):
        for j in range(n-1, i, -1):
            if arr[j] > arr[i]:
                lds[i] = max(lds[i], lds[j] + 1)

    # Find the maximum value between the last element of LIS and the first element of LDS
    result = max(lis[-1], lds[0])

    # Calculate the actual length of the longest bitonic subsequence
    for i in range(n):
        if lis[i] + lds[i] - 1 == result:
            return lis[i] + lds[i] - 1

