def check_abundant(n):
    # Find all divisors of n excluding itself
    divisors_sum = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors_sum += i
            if i != n // i:
                divisors_sum += n // i

    # Check if the sum of divisors is greater than twice the original number
    return divisors_sum > 2 * n

