def find_Max(arr, low, high):
    # Base case: If there's only one element
    if low == high:
        return arr[low]

    # Find the middle index
    mid = (low + high) // 2

    # Check if the middle element is greater than its predecessor
    if arr[mid] > arr[mid - 1]:
        return arr[mid]

    # If the left half of the array is sorted
    if arr[low] <= arr[mid]:
        # Recursively search in the right half
        return find_Max(arr, mid + 1, high)

    # If the right half of the array is sorted
    return find_Max(arr, low, mid - 1)

