def sum_of_product(n):
    # Base case for n=0 or n=1
    if n == 0:
        return 0
    elif n == 1:
        return 1

    # Initialize the first row with values from Pascal's Triangle
    dp = [[0 for _ in range(i+1)] for i in range(n)]
    dp[0][0] = 1

    # Fill up the DP table using the formula derived from Pascal's Triangle
    for i in range(1, n):
        for j in range(i+1):
            if j == 0:
                dp[i][j] = dp[i-1][j] + dp[i-1][j+1]
            elif j == i:
                dp[i][j] = dp[i-1][j-1] + dp[i-1][j]
            else:
                dp[i][j] = dp[i-1][j-1] + dp[i-1][j] + dp[i-1][j+1]

    # The answer will be at dp[n-1][n//2]
    return dp[n-1][n//2]

