def find_kth(arr1, arr2, m, n, k):
    # Base case: If one array is empty, return the k-th element from the other array
    if not arr1:
        return arr2[k-1]
    if not arr2:
        return arr1[k-1]

    # Find the middle elements of both arrays
    mid1 = m // 2
    mid2 = n // 2

    # Check if the k-th element lies in the left half or right half of either array
    if arr1[mid1] > arr2[mid2]:
        return find_kth(arr1[:mid1], arr2, m, n-mid1, k)
    else:
        return find_kth(arr1, arr2[:mid2], m-mid2, n, k-mid2)

def get_sum(n):
    sum = 0
    i = 1
    while i <= int(math.sqrt(n)):
        if n % i == 0:
            if n // i == i:
                sum += i
            else:
                sum += i
                sum += (n // i)
        i += 1
    return sum

